using Eduscape.Domain.Common;
using Eduscape.Domain.Rooms;
using Eduscape.Infrastructure.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Eduscape.Infrastructure.Persistence.Configurations;

// Ids are generated by the domain (Guid v7), so EF must never treat a set key as "already saved".
internal sealed class EscapeRoomConfiguration : IEntityTypeConfiguration<EscapeRoom>
{
    public void Configure(EntityTypeBuilder<EscapeRoom> builder)
    {
        builder.ToTable("EscapeRooms");
        builder.Property(r => r.Id).ValueGeneratedNever();
        builder.Property(r => r.Title).HasMaxLength(TextLimits.Title);
        builder.Ignore(r => r.StartScene);
        builder.Ignore(r => r.Objects);

        // Each editor save increases the revision, so a save based on an older revision fails instead of overwriting.
        builder.Property(r => r.Revision).IsConcurrencyToken();

        builder.HasMany(r => r.Scenes)
            .WithOne()
            .HasForeignKey(s => s.EscapeRoomId)
            .OnDelete(DeleteBehavior.Cascade);

        // The room library is filtered by subject and grade level.
        builder.HasIndex(r => new { r.Subject, r.GradeLevel });
        builder.HasIndex(r => r.OwnerTeacherId);

        // Templates have no owner. Accounts cannot be deleted yet, so an owner is never removed from under its rooms.
        builder.HasOne<Teacher>()
            .WithMany()
            .HasForeignKey(r => r.OwnerTeacherId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}

internal sealed class SceneConfiguration : IEntityTypeConfiguration<Scene>
{
    public void Configure(EntityTypeBuilder<Scene> builder)
    {
        builder.ToTable("Scenes");
        builder.Property(s => s.Id).ValueGeneratedNever();
        builder.Property(s => s.Name).HasMaxLength(TextLimits.Name);
        builder.Property(s => s.Narration).HasMaxLength(TextLimits.Narration);
        builder.Property(s => s.BackgroundImageKey).HasMaxLength(TextLimits.StorageKey);

        builder.HasMany(s => s.Objects)
            .WithOne()
            .HasForeignKey(o => o.SceneId)
            .OnDelete(DeleteBehavior.Cascade);

        // At most one start scene per room.
        builder.HasIndex(s => s.EscapeRoomId)
            .IsUnique()
            .HasFilter("\"IsStartScene\"")
            .HasDatabaseName("IX_Scenes_EscapeRoomId_StartScene");
    }
}

internal sealed class RoomObjectConfiguration : IEntityTypeConfiguration<RoomObject>
{
    public void Configure(EntityTypeBuilder<RoomObject> builder)
    {
        builder.ToTable("RoomObjects");
        builder.Property(o => o.Id).ValueGeneratedNever();
        builder.Ignore(o => o.Type);

        builder.HasDiscriminator<RoomObjectType>("ObjectType")
            .HasValue<Lock>(RoomObjectType.Lock)
            .HasValue<Letter>(RoomObjectType.Letter)
            .HasValue<Door>(RoomObjectType.Door)
            .HasValue<ExitDoor>(RoomObjectType.ExitDoor);

        builder.ComplexProperty(o => o.Position, position =>
        {
            position.Property(p => p.X).HasColumnName("PositionX");
            position.Property(p => p.Y).HasColumnName("PositionY");
        });

        builder.Property(o => o.GraphicKey).HasMaxLength(TextLimits.StorageKey);
        builder.Property(o => o.UnlockedGraphicKey).HasMaxLength(TextLimits.StorageKey);

        // Deleting the source makes the dependent visible from start rather than deleting it.
        builder.HasOne<RoomObject>()
            .WithMany()
            .HasForeignKey(o => o.UnlockedById)
            .OnDelete(DeleteBehavior.SetNull);
    }
}

internal sealed class LockConfiguration : IEntityTypeConfiguration<Lock>
{
    public void Configure(EntityTypeBuilder<Lock> builder)
    {
        builder.Property(l => l.Question).HasMaxLength(TextLimits.Question);
        builder.Property(l => l.CorrectAnswer).HasMaxLength(TextLimits.Answer);
        builder.Property(l => l.Tolerance).HasPrecision(18, 6);
        builder.Property(l => l.Hint).HasMaxLength(TextLimits.Hint);
    }
}

internal sealed class LetterConfiguration : IEntityTypeConfiguration<Letter>
{
    public void Configure(EntityTypeBuilder<Letter> builder) =>
        builder.Property(l => l.Text).HasMaxLength(TextLimits.LetterText);
}

internal sealed class DoorConfiguration : IEntityTypeConfiguration<Door>
{
    public void Configure(EntityTypeBuilder<Door> builder) =>
        builder.HasOne<Scene>()
            .WithMany()
            .HasForeignKey(d => d.TargetSceneId)
            .OnDelete(DeleteBehavior.SetNull);
}
